cssCode:
#container {
  display: flex; justify-content: center; align-items: center; background: #0a0a0f;
}
.liquid-text-wrap {
  position: relative; overflow: hidden;
}
.liquid-text {
  font-family: 'Poppins', sans-serif; font-size: 60px; font-weight: 900;
  color: transparent; text-transform: uppercase;
  background: linear-gradient(90deg, #ff007f, #00d2ff, #ff007f);
  background-size: 200%; -webkit-background-clip: text;
  animation: colorFlow 4s linear infinite; filter: url(#liquid-filter);
}
@keyframes colorFlow { 0% { background-position: 0% 50%; } 100% { background-position: 100% 50%; } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;justify-content:center;align-items:center;background:#0a0a0f;overflow:hidden;position:relative;';

c.innerHTML = `
  <svg style="position:absolute; width:0; height:0;">
    <filter id="liquid-filter">
      <feTurbulence type="fractalNoise" baseFrequency="0.02" numOctaves="3" result="noise" id="turb" />
      <feDisplacementMap in="SourceGraphic" in2="noise" scale="20" xChannelSelector="R" yChannelSelector="G" />
    </filter>
  </svg>
  <div class="liquid-text-wrap">
    <h1 class="liquid-text">ZYNK</h1>
  </div>
`;

const turb = document.getElementById('turb');
let time = 0;
function animateTurbulence() {
  time += 0.01;
  // પવનની લહેરખીની જેમ ટેક્સ્ટને વાંકુંચૂંકું કરે છે (SVG Filter Animation)
  turb.setAttribute('baseFrequency', `0.02 ${0.02 + Math.sin(time)*0.01}`);
  requestAnimationFrame(animateTurbulence);
}
animateTurbulence();
